.pengiriman-tab{display:flex;gap:8px;border-bottom:1px solid var(--garis,#b8c3b4);margin:0 0 24px;padding-bottom:10px;flex-wrap:wrap}.pengiriman-tab a{display:inline-flex;align-items:center;padding:10px 16px;border-radius:8px;color:inherit;text-decoration:none;min-height:44px}.pengiriman-tab a[aria-current]{font-weight:600;background:var(--bidang-aktif,rgba(102,135,94,.16))}.pengiriman-tab a:focus-visible,.retur-asal input:focus-visible,.retur-asal select:focus-visible,.retur-asal textarea:focus-visible{outline:2px solid currentColor;outline-offset:3px}.retur-asal{max-width:1100px;margin:auto}.retur-asal__panel{border:1px solid var(--garis,#b8c3b4);border-radius:12px;padding:20px;margin:16px 0}.retur-asal__baris{display:grid;grid-template-columns:minmax(170px,2fr) repeat(3,minmax(80px,1fr)) minmax(110px,1fr);gap:16px;align-items:center;padding:16px 0;border-bottom:1px solid var(--garis,#b8c3b4)}.retur-asal__baris small{display:block;opacity:.8}.retur-asal label{display:block}.retur-asal input,.retur-asal select,.retur-asal textarea{font:inherit;color:inherit;background:var(--bidang,transparent);border:1px solid var(--garis,#b8c3b4);border-radius:6px;padding:10px;min-height:44px;max-width:100%;box-sizing:border-box}.retur-asal input[type=number]{width:100%}.retur-asal textarea{width:100%;min-height:80px}.retur-asal__pesan{border-left:4px solid #b37a25;padding:12px 16px;background:rgba(191,145,48,.12);margin:16px 0}.retur-asal__aksi{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}.retur-asal details pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.retur-asal .btn{min-height:44px}.retur-asal__tiket{width:100%;margin:8px 0 20px}@media(max-width:600px){.retur-asal__panel{padding:14px}.retur-asal__baris{grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.retur-asal__nama{grid-column:1/-1}.retur-asal__jumlah{grid-column:1/-1}.retur-asal__aksi .btn{width:100%}}

